'use strict';
(() => {
  const Academic=window.FestacolAcademicAdmin={wizard:null};
  const streamTone=(stream)=>stream==='Science'?'#315efb':stream==='Arts'?'#7c3aed':stream==='Social Science'?'#0f9f8f':stream==='Qualifier'?'#f59e0b':'#64748b';
  const reportView=()=>['overview','exams','students','placements','promotions','integrity'].includes(p().get('view'))?p().get('view'):'overview';
  const submittedAttempts=()=>Store.getAttempts().filter(a=>a.submittedAt);
  const mean=(values)=>values.length?Math.round(values.reduce((a,b)=>a+(Number(b)||0),0)/values.length):0;

  function classesPage(){
    const classes=Store.listClasses(),users=Store.listUsers(),sessions=Store.listSessions();
    root.innerHTML=`<div class="page-enter">${pageHead('Academic structure','Classes','Organize cohorts by senior class level and stream, including the incoming SS1 qualifier pool.',`<button class="btn btn-primary" data-modal="class-create">${ICON.plus} New class</button>`)}
      <div class="space-y-5">${['SS1','SS2','SS3'].map(level=>{const levelClasses=classes.filter(c=>c.classLevel===level);return`<section class="class-level-section"><div class="mb-4 flex items-center justify-between"><div><p class="eyebrow">${level}</p><h3 class="section-title mt-1">${level} academic groups</h3></div><span class="badge badge-neutral">${levelClasses.length} groups</span></div><div class="class-stream-grid">${levelClasses.map(cls=>{const count=users.filter(u=>u.role==='student'&&u.classId===cls.id).length,exams=sessions.filter(s=>s.classLevel===level&&(s.classGroup===cls.stream||s.classGroup==='General')).length;return`<article class="class-stream-card" style="--stream-color:${streamTone(cls.stream)}"><div class="flex items-start justify-between gap-3"><div><span class="badge badge-neutral">${e(cls.stream)}</span><h4 class="mt-3 font-display text-lg font-extrabold text-slate-950">${e(cls.name)}</h4><p class="mt-1 text-xs text-slate-500">${e(cls.room||'Room not assigned')} · ${e(cls.academicSession)}</p></div><button class="icon-btn size-9" data-detail="class" data-id="${e(cls.id)}" aria-label="Manage ${e(cls.name)}">${ICON.more}</button></div><div class="mt-4 grid grid-cols-3 gap-2"><div class="mini-metric"><span>Students</span><strong>${count}</strong></div><div class="mini-metric"><span>Capacity</span><strong>${cls.capacity}</strong></div><div class="mini-metric"><span>Exams</span><strong>${exams}</strong></div></div></article>`;}).join('')}</div></section>`;}).join('')}</div></div>`;
  }

  function classModal(){
    openModal(`<div class="p-6"><div class="flex items-start justify-between gap-4"><div><p class="eyebrow">Academic structure</p><h2 id="admin-modal-title" class="mt-1 font-display text-2xl font-extrabold">Create class group</h2><p class="mt-2 text-sm text-slate-600">Choose level and stream first; type only the details that cannot be inferred.</p></div><button class="icon-btn" data-modal-close aria-label="Close">${ICON.close}</button></div><form id="class-v3-form" class="mt-6 space-y-5"><div><p class="text-xs font-bold text-slate-600">Class level</p><div class="segmented mt-2 grid grid-cols-3">${['SS1','SS2','SS3'].map(x=>`<button type="button" data-class-v3-level="${x}" aria-pressed="${x==='SS1'}">${x}</button>`).join('')}</div></div><div><p class="text-xs font-bold text-slate-600">Academic group</p><div class="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-5">${['Qualifier','Science','Arts','Social Science','General'].map((x,i)=>`<button type="button" class="track-card min-h-20" data-class-v3-stream="${e(x)}" aria-pressed="${i===0}"><strong>${e(x)}</strong></button>`).join('')}</div></div><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">Capacity<input id="class-v3-capacity" type="number" min="1" max="500" class="field mt-2" value="60"></label><label class="text-sm font-bold">Room<input id="class-v3-room" class="field mt-2" placeholder="e.g. Science Wing"></label></div><button class="btn btn-primary w-full" type="submit">Create class group</button></form></div>`);
  }

  function examsPage(){
    const all=Store.listSessions(),attempts=Store.getAttempts();
    root.innerHTML=`<div class="page-enter">${pageHead('Assessment operations','Exams','Configure papers, monitor candidate performance, inspect integrity signals and manage attempt lifecycle.',`<button class="btn btn-primary" data-open-exam-wizard>${ICON.plus} Create exam</button>`)}<section class="kpi-grid">${kpi('Exam sessions',all.length,'all configured sessions','brand')}${kpi('Live',all.filter(s=>sessionState(s)==='open').length,'currently available','teal')}${kpi('Submissions',attempts.filter(a=>a.submittedAt).length,'locked candidate attempts','violet')}${kpi('In progress',attempts.filter(a=>a.startedAt&&!a.submittedAt).length,'resumable attempts','amber')}</section><section class="surface mt-5 overflow-hidden">${all.length?examTable(all):empty('No exams configured','Create the first examination session.',ART.auth,`<button class="btn btn-primary" data-open-exam-wizard>Create exam</button>`)}</section></div>`;
  }

  const ensureWizard=()=>Academic.wizard||(Academic.wizard={mode:'qualifier',classLevel:'SS1',classGroup:'Qualifier',subjects:['q-eng','q-math','q-bst','q-social'],tracks:['Science','Arts','Social Science'],durationSeconds:1800,questionCount:10,status:'open',title:''});
  const wizardSubjects=(w)=>data.subjectCatalog.filter(s=>s.levels.includes(w.classLevel)&&data.questions.some(q=>q.subjectCode===s.code&&q.levels.includes(w.classLevel)&&q.examModes.includes(w.mode)));
  const availableCount=(w)=>data.questions.filter(q=>q.levels.includes(w.classLevel)&&q.examModes.includes(w.mode)&&w.subjects.includes(q.subjectCode)).length;
  function examWizard(){
    const w=ensureWizard(),step=Math.max(1,Math.min(5,Number(p().get('step'))||1));
    const steps=['Scope','Coverage','Paper','Integrity','Review'];
    const maxQ=Math.max(1,availableCount(w)); if(w.questionCount>maxQ)w.questionCount=maxQ;
    const body=step===1?`<div class="grid gap-5"><div><p class="text-xs font-bold text-slate-600">Exam type</p><div class="mt-2 grid gap-2 sm:grid-cols-2">${[['qualifier','Placement qualifier'],['mixed','Mixed subjects'],['single','Single subject'],['waec','WAEC practice']].map(([k,l])=>`<button type="button" class="track-card" data-v3-mode="${k}" aria-pressed="${w.mode===k}"><strong>${l}</strong><small class="mt-2 block text-slate-500">${k==='qualifier'?'Adaptive SS1 stream placement':k==='mixed'?'One paper across several subjects':k==='single'?'Focused class assessment':'SS3 subject practice'}</small></button>`).join('')}</div></div><div><p class="text-xs font-bold text-slate-600">Class level</p><div class="segmented mt-2 grid grid-cols-3">${['SS1','SS2','SS3'].map(x=>`<button type="button" data-v3-level="${x}" aria-pressed="${w.classLevel===x}">${x}</button>`).join('')}</div></div><div><p class="text-xs font-bold text-slate-600">Class group</p><div class="mt-2 flex flex-wrap gap-2">${['Qualifier','Science','Arts','Social Science','General'].map(x=>`<button type="button" class="btn btn-secondary btn-sm" data-v3-group="${e(x)}" aria-pressed="${w.classGroup===x}">${e(x)}</button>`).join('')}</div></div></div>`:
    step===2?`<div class="grid gap-5">${w.mode==='qualifier'?`<div><p class="text-xs font-bold text-slate-600">Eligible placement tracks</p><div class="mt-2 grid gap-2 sm:grid-cols-3">${Store.TRACKS.map(x=>`<button type="button" class="track-card" data-v3-track="${e(x)}" aria-pressed="${w.tracks.includes(x)}"><strong>${e(x)}</strong><small class="mt-2 block text-slate-500">Candidate can be recommended here</small></button>`).join('')}</div></div>`:''}<div><p class="text-xs font-bold text-slate-600">Subject combination</p><div class="mt-2 grid gap-2 sm:grid-cols-2">${wizardSubjects(w).map(s=>`<button type="button" class="track-card min-h-20" data-v3-subject="${e(s.code)}" aria-pressed="${w.subjects.includes(s.code)}"><strong>${e(s.label)}</strong><small class="mt-1 block text-slate-500">${e(s.code)}</small></button>`).join('')}</div></div></div>`:
    step===3?`<div class="grid gap-6"><div><div class="flex items-center justify-between"><label for="duration-range" class="text-sm font-extrabold">Duration</label><strong id="duration-value" class="badge badge-brand">${e(Store.durationLabel(w.durationSeconds))}</strong></div><input id="duration-range" class="range-control mt-4" type="range" min="30" max="10800" step="30" value="${w.durationSeconds}"><div class="mt-2 flex justify-between text-xs text-slate-500"><span>30 sec</span><span>3 hrs</span></div></div><div><div class="flex items-center justify-between"><label for="question-count-range" class="text-sm font-extrabold">Total questions</label><strong id="question-count-value" class="badge badge-brand">${w.questionCount}</strong></div><input id="question-count-range" class="range-control mt-4" type="range" min="1" max="${maxQ}" value="${w.questionCount}"><div class="mt-2 text-xs text-slate-500">Maximum available for this configuration: ${maxQ}</div></div></div>`:
    step===4?`<div class="grid gap-4"><p class="text-sm text-slate-600">Choose how the browser should observe integrity signals. These are advisory prototype controls, not tamper-proof invigilation.</p>${[['focus','Monitor tab/window changes',true],['fullscreen','Prompt fullscreen',true],['clipboard','Block clipboard actions',true]].map(([k,l,on])=>`<label class="control-row"><span><strong class="text-sm text-slate-900">${l}</strong></span><input data-v3-integrity="${k}" type="checkbox" ${on?'checked':''}></label>`).join('')}<div><p class="text-xs font-bold text-slate-600">Initial exam status</p><div class="segmented mt-2 grid grid-cols-3">${['open','draft','closed'].map(x=>`<button type="button" data-v3-status="${x}" aria-pressed="${w.status===x}">${x}</button>`).join('')}</div></div></div>`:
    `<div class="grid gap-4"><label class="text-sm font-bold">Exam title<input id="v3-title" class="field mt-2" value="${e(w.title||`${w.classLevel} ${w.mode==='qualifier'?'Placement Qualifier':'Assessment'}`)}"></label><div class="surface-soft p-4"><div class="grid gap-3 sm:grid-cols-2"><div><span class="eyebrow">Mode</span><strong class="mt-1 block">${e(Store.getModeLabel(w.mode))}</strong></div><div><span class="eyebrow">Class</span><strong class="mt-1 block">${e(w.classLevel)} · ${e(w.classGroup)}</strong></div><div><span class="eyebrow">Paper</span><strong class="mt-1 block">${w.questionCount} questions · ${e(Store.durationLabel(w.durationSeconds))}</strong></div><div><span class="eyebrow">Placement</span><strong class="mt-1 block">${e(w.mode==='qualifier'?w.tracks.join(', '):'Not applicable')}</strong></div></div></div></div>`;
    openModal(`<div class="p-5 sm:p-6"><div class="flex items-start justify-between gap-4"><div><p class="eyebrow">Exam builder</p><h2 id="admin-modal-title" class="mt-1 font-display text-2xl font-extrabold">Create examination</h2></div><button class="icon-btn" data-modal-close aria-label="Close">${ICON.close}</button></div><div class="wizard-v3-stepper mt-6">${steps.map((s,i)=>`<div class="wizard-v3-step" ${i+1===step?'aria-current="step"':''} data-complete="${i+1<step}"><span>0${i+1}</span><strong>${s}</strong></div>`).join('')}</div><div class="mt-6">${body}</div><div class="mt-6 flex justify-between gap-3">${step>1?'<button class="btn btn-secondary" data-v3-prev>Back</button>':'<span></span>'}<button class="btn btn-primary" data-v3-next>${step===5?'Create & generate link':'Continue'}</button></div></div>`);
  }

  function examDrawer(id){
    const s=Store.listSessions().find(x=>x.id===id);if(!s)return openDrawer('<div class="p-6">Exam not found.</div>');const ats=Store.attemptsForSession(id),submitted=ats.filter(a=>a.submittedAt),avg=mean(submitted.map(a=>a.score));
    openDrawer(`<div class="p-5"><div class="flex items-start justify-between"><div><p class="eyebrow">Exam intelligence</p><h2 class="mt-1 font-display text-2xl font-extrabold">${e(s.title)}</h2></div><button class="icon-btn" data-drawer-close>${ICON.close}</button></div><div class="student-metric-grid mt-5">${[['Candidates',ats.length],['Submitted',submitted.length],['Average',`${avg}%`],['Integrity',`${mean(submitted.map(a=>a.integrityScore??100))}%`]].map(([l,v])=>`<div class="mini-metric"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="mt-5"><label class="text-xs font-bold text-slate-600">Dynamic link<input data-session-link class="field mt-2" readonly value="${e(Store.getSessionLink(s,location.href))}"></label></div><h3 class="section-title mt-6">Candidate performance</h3><div class="mt-3 divide-y divide-slate-100">${ats.length?ats.map(a=>`<div class="py-3"><div class="flex items-center justify-between gap-3"><div><strong class="text-sm">${e(a.studentName||'Candidate')}</strong><p class="text-xs text-slate-500">${a.submittedAt?`Score ${a.score??0}% · Integrity ${a.integrityScore??100}%`:`In progress · ${Math.ceil(a.remainingSeconds??0)} sec remaining`}</p></div>${a.submittedAt?statusBadge('submitted'):`<button class="btn btn-danger btn-sm" data-reset-attempt data-session-id="${e(id)}" data-candidate-hash="${e(a.candidateHash)}">Reset unfinished</button>`}</div></div>`).join(''):'<p class="py-5 text-sm text-slate-500">No candidate attempts yet.</p>'}</div></div>`);
  }

  function userDrawer(id){
    const u=Store.listUsers().find(x=>x.id===id);if(!u)return openDrawer('<div class="p-6">Student not found.</div>');const candidates=Store.getAttempts().filter(a=>a.studentName?.toLowerCase()===u.fullName.toLowerCase()),done=candidates.filter(a=>a.submittedAt);openDrawer(`<div class="p-5"><div class="flex items-start justify-between"><div><p class="eyebrow">Student report</p><h2 class="mt-1 font-display text-2xl font-extrabold">${e(u.fullName)}</h2><p class="text-sm text-slate-500">${e(classFor(u.classId)?.name||'No class')} · ${e(u.academicSession)}</p></div><button class="icon-btn" data-drawer-close>${ICON.close}</button></div><div class="student-metric-grid mt-5">${[['Exams',done.length],['Average',`${mean(done.map(a=>a.score))}%`],['Pace',mean(done.map(a=>a.paceIndex))],['Integrity',`${mean(done.map(a=>a.integrityScore??100))}%`]].map(([l,v])=>`<div class="mini-metric"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><h3 class="section-title mt-6">Exam history</h3><div class="mt-3 divide-y divide-slate-100">${candidates.map(a=>`<div class="py-3"><strong class="text-sm">${e(a.sessionTitle)}</strong><p class="text-xs text-slate-500">${a.submittedAt?`${a.score??0}% · ${a.completion??100}% complete`:'In progress'}</p></div>`).join('')||'<p class="text-sm text-slate-500">No exam activity.</p>'}</div></div>`);
  }

  function reportsPage(){
    const view=reportView(),ats=submittedAttempts(),tabs=[['overview','Overview'],['exams','Exams'],['students','Students'],['placements','Placements'],['promotions','Promotions'],['integrity','Integrity']];let content='';
    if(view==='overview')content=`<section class="kpi-grid">${kpi('Submissions',ats.length,'completed attempts','brand')}${kpi('Average',`${mean(ats.map(a=>a.score))}%`,'all scored exams','teal')}${kpi('Integrity',`${mean(ats.map(a=>a.integrityScore??100))}%`,'browser signal score','violet')}${kpi('Placements',ats.filter(a=>a.placement).length,'qualifier recommendations','amber')}</section>`;
    if(view==='exams')content=`<section class="surface overflow-hidden"><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Exam</th><th>Submissions</th><th>Average</th><th>Integrity</th></tr></thead><tbody>${Store.listSessions().map(s=>{const rows=ats.filter(a=>a.sessionId===s.id);return`<tr><td>${e(s.title)}</td><td>${rows.length}</td><td>${mean(rows.map(a=>a.score))}%</td><td>${mean(rows.map(a=>a.integrityScore??100))}%</td></tr>`;}).join('')}</tbody></table></div></section>`;
    if(view==='students')content=`<section class="surface overflow-hidden"><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Student</th><th>Attempts</th><th>Average</th><th>Pace</th><th>Integrity</th></tr></thead><tbody>${Store.listUsers().filter(u=>u.role==='student').map(u=>{const rows=ats.filter(a=>a.studentName?.toLowerCase()===u.fullName.toLowerCase());return`<tr><td>${e(u.fullName)}</td><td>${rows.length}</td><td>${mean(rows.map(a=>a.score))}%</td><td>${mean(rows.map(a=>a.paceIndex))}</td><td>${mean(rows.map(a=>a.integrityScore??100))}%</td></tr>`;}).join('')}</tbody></table></div></section>`;
    if(view==='placements')content=`<section class="surface p-5"><h3 class="section-title">Qualifier placements</h3><div class="mt-4 grid gap-3">${ats.filter(a=>a.placement).map(a=>`<div class="attention-row"><div class="flex-1"><strong>${e(a.studentName)}</strong><p class="text-xs text-slate-500">${e(a.sessionTitle)}</p></div>${statusBadge(a.placement.assignedTrack)}<strong>${a.placement.confidence}%</strong></div>`).join('')||'<p class="text-sm text-slate-500">No qualifier results yet.</p>'}</div></section>`;
    if(view==='promotions')content=`<section class="surface p-5"><h3 class="section-title">Promotion readiness</h3><div class="mt-4 grid gap-3">${Store.listUsers().filter(u=>u.role==='student').map(u=>`<div class="attention-row"><div class="flex-1"><strong>${e(u.fullName)}</strong><p class="text-xs text-slate-500">${e(classFor(u.classId)?.name||'Unassigned')}</p></div>${statusBadge(u.promotionStatus||'review')}</div>`).join('')}</div></section>`;
    if(view==='integrity')content=`<section class="surface p-5"><h3 class="section-title">Integrity signals</h3><div class="mt-4 grid gap-3">${ats.filter(a=>(a.integrityEvents||[]).length).flatMap(a=>a.integrityEvents.map(ev=>`<div class="integrity-event"><span class="integrity-dot"></span><div><strong class="text-sm">${e(a.studentName)} · ${e(ev.type)}</strong><p class="text-xs text-slate-500">${e(a.sessionTitle)} · ${new Date(ev.at).toLocaleString('en-NG')}</p></div></div>`)).join('')||'<p class="text-sm text-slate-500">No integrity exceptions recorded.</p>'}</div></section>`;
    root.innerHTML=`<div class="page-enter">${pageHead('Academic intelligence','Reports','Drill into exam, student, placement, promotion and integrity outcomes.',`<button class="btn btn-secondary" data-report-refresh>Refresh data</button>`)}<nav class="report-tabs mb-5">${tabs.map(([k,l])=>`<a href="${href('reports',{view:k})}" ${view===k?'aria-current="page"':''}>${l}</a>`).join('')}</nav>${content}</div>`;
  }

  document.addEventListener('click',(event)=>{
    const lvl=event.target.closest('[data-class-v3-level]');if(lvl){modal.querySelectorAll('[data-class-v3-level]').forEach(x=>x.setAttribute('aria-pressed',String(x===lvl)));const qualifier=modal.querySelector('[data-class-v3-stream="Qualifier"]');if(qualifier)qualifier.hidden=lvl.dataset.classV3Level!=='SS1';return;}
    const stream=event.target.closest('[data-class-v3-stream]');if(stream){modal.querySelectorAll('[data-class-v3-stream]').forEach(x=>x.setAttribute('aria-pressed',String(x===stream)));return;}
    const mode=event.target.closest('[data-v3-mode]');if(mode){const w=ensureWizard();w.mode=mode.dataset.v3Mode;if(w.mode==='qualifier'){w.classLevel='SS1';w.classGroup='Qualifier';w.subjects=['q-eng','q-math','q-bst','q-social'];w.tracks=[...Store.TRACKS];}else if(w.mode==='waec'){w.classLevel='SS3';w.classGroup='General';w.subjects=[];}else w.subjects=[];examWizard();return;}
    const level=event.target.closest('[data-v3-level]');if(level){const w=ensureWizard();if(w.mode==='qualifier'&&level.dataset.v3Level!=='SS1')return;if(w.mode==='waec'&&level.dataset.v3Level!=='SS3')return;w.classLevel=level.dataset.v3Level;w.subjects=[];examWizard();return;}
    const group=event.target.closest('[data-v3-group]');if(group){ensureWizard().classGroup=group.dataset.v3Group;examWizard();return;}
    const track=event.target.closest('[data-v3-track]');if(track){const w=ensureWizard(),v=track.dataset.v3Track;w.tracks=w.tracks.includes(v)?w.tracks.filter(x=>x!==v):[...w.tracks,v];if(!w.tracks.length)w.tracks=[v];examWizard();return;}
    const subject=event.target.closest('[data-v3-subject]');if(subject){const w=ensureWizard(),v=subject.dataset.v3Subject;if(w.mode==='single'||w.mode==='waec')w.subjects=[v];else w.subjects=w.subjects.includes(v)?w.subjects.filter(x=>x!==v):[...w.subjects,v];examWizard();return;}
    const status=event.target.closest('[data-v3-status]');if(status){ensureWizard().status=status.dataset.v3Status;examWizard();return;}
    if(event.target.closest('[data-v3-prev]')){navigate('exams',{modal:'exam-create',step:Math.max(1,(Number(p().get('step'))||1)-1)});return;}
    if(event.target.closest('[data-v3-next]')){const w=ensureWizard(),step=Number(p().get('step'))||1;if(step===2){if(w.mode==='qualifier'&&!w.tracks.length)return announce('Choose at least one eligible placement track.','danger');if((w.mode==='single'||w.mode==='waec')&&w.subjects.length!==1)return announce('Choose one subject.','danger');if(w.mode==='mixed'&&w.subjects.length<2)return announce('Choose at least two subjects.','danger');if(w.mode==='qualifier'&&!w.subjects.length)return announce('Choose qualifier subjects.','danger');}if(step<5){navigate('exams',{modal:'exam-create',step:step+1});return;}w.title=document.getElementById('v3-title')?.value||w.title;try{const created=Store.saveSession({mode:w.mode,classLevel:w.classLevel,classGroup:w.classGroup,subjects:w.subjects,placementTracks:w.tracks,durationSeconds:w.durationSeconds,questionCount:w.questionCount,status:w.status,title:w.title,integrityPolicy:{focusMonitoring:true,fullscreenPrompt:true,clipboardGuard:true,warnAfter:2},randomization:{questionOrder:true,optionOrder:true,minimizePaperCollisions:true}});openModal(`<div class="p-6"><span class="badge badge-success">Exam created</span><h2 id="admin-modal-title" class="mt-3 font-display text-2xl font-extrabold">Dynamic link ready</h2><p class="mt-2 text-sm text-slate-600">Share this exact link or its QR code with candidates.</p><input data-session-link class="field mt-5" readonly value="${e(Store.getSessionLink(created,location.href))}"><div class="mt-5 flex gap-3"><button class="btn btn-primary" data-modal-close>Done</button><button class="btn btn-secondary" data-detail="exam" data-id="${e(created.id)}">Open exam report</button></div></div>`);Academic.wizard=null;}catch(err){announce(err.message,'danger');}return;}
    const reset=event.target.closest('[data-reset-attempt]');if(reset){try{Store.resetUnfinishedAttempt(reset.dataset.sessionId,reset.dataset.candidateHash);toast('Unfinished attempt reset. The candidate may authenticate and start again.','success');examDrawer(reset.dataset.sessionId);}catch(err){toast(err.message,'danger');}return;}
  },true);
  document.addEventListener('input',(event)=>{if(event.target.id==='duration-range'){const w=ensureWizard();w.durationSeconds=Number(event.target.value);document.getElementById('duration-value').textContent=Store.durationLabel(w.durationSeconds);}if(event.target.id==='question-count-range'){const w=ensureWizard();w.questionCount=Number(event.target.value);document.getElementById('question-count-value').textContent=String(w.questionCount);}},true);
  document.addEventListener('submit',(event)=>{if(event.target.id!=='class-v3-form')return;event.preventDefault();const level=modal.querySelector('[data-class-v3-level][aria-pressed="true"]')?.dataset.classV3Level||'SS1',stream=modal.querySelector('[data-class-v3-stream][aria-pressed="true"]')?.dataset.classV3Stream||'General';Store.saveClass({classLevel:level,stream,group:stream,capacity:Number(document.getElementById('class-v3-capacity').value),room:document.getElementById('class-v3-room').value});closeModal();toast('Class group created.','success');render();},true);

  window.classesPage=classesPage; window.classModal=classModal; window.examsPage=examsPage; window.examWizard=examWizard; window.examDrawer=examDrawer; window.userDrawer=userDrawer; window.reportsPage=reportsPage;
  window.FestacolAcademicAdmin={placementReports:()=>submittedAttempts().filter(a=>a.placement),promotionReports:()=>Store.listUsers().filter(u=>u.role==='student'),integrityReports:()=>submittedAttempts().flatMap(a=>a.integrityEvents||[])};
})();
